package io.knowledgebrain.media;
import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_MEDIA_DATABASE_URL",matches=".+")
class DomainMediaStoreIntegrationTest {
 MediaStoreIntegrationTest f;DomainMediaStore store;DomainMediaStore.Scope scope;
 @BeforeEach void setup(){f=new MediaStoreIntegrationTest();f.setup();store=new DomainMediaStore(f.source,f.store);scope=new DomainMediaStore.Scope(f.ids.next(),f.ids.next(),f.ids.next());}
 @Test void allocationRetrySurvivesRestartAndCompletionWithoutSecondQuota(){String key="a".repeat(32);var a=store.create(scope,key,f.input(42),f.trace);f.store.complete(scope.spaceId(),a.media().mediaId(),scope.ownerId(),"sealed-version",f.trace);store=new DomainMediaStore(f.source,f.store);var replay=store.create(scope,key,f.input(42),f.trace);assertEquals("AVAILABLE",replay.media().state());assertEquals(a.media().mediaId(),replay.media().mediaId());assertEquals(1,f.store.list(scope.spaceId(),null,100).items().size());assertEquals(2,f.jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,a.media().mediaId()));assertEquals(409,assertThrows(ResponseStatusException.class,()->store.create(scope,key,f.input(43),f.trace)).getStatusCode().value());}
 @Test void wrongOwnerContextSpaceAndPersonalFileCannotBeUsed(){var a=store.create(scope,"a".repeat(32),f.input(42),f.trace);for(var wrong:List.of(new DomainMediaStore.Scope(scope.spaceId(),scope.contextId(),f.ids.next()),new DomainMediaStore.Scope(scope.spaceId(),f.ids.next(),scope.ownerId()),new DomainMediaStore.Scope(f.ids.next(),scope.contextId(),scope.ownerId())))assertEquals(404,assertThrows(ResponseStatusException.class,()->store.get(wrong,a.media().mediaId())).getStatusCode().value());var personal=f.store.create(scope.spaceId(),scope.ownerId(),f.input(42),f.trace);assertEquals(404,assertThrows(ResponseStatusException.class,()->store.get(scope,personal.mediaId())).getStatusCode().value());}
 @Test void failedAllocationRollsBackMetadataQuotaAndOutbox(){String constraint="allocation_fail_"+scope.spaceId().toString().replace("-","");f.jdbc.execute("ALTER TABLE domain_media_allocation ADD CONSTRAINT "+constraint+" CHECK(owner_id<>'"+scope.ownerId()+"') NOT VALID");try{assertThrows(RuntimeException.class,()->store.create(scope,"a".repeat(32),f.input(42),f.trace));assertTrue(f.store.list(scope.spaceId(),null,100).items().isEmpty());assertEquals(0,f.jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid IN (SELECT media_id FROM media WHERE space_id=?)",Integer.class,scope.spaceId()));}finally{f.jdbc.execute("ALTER TABLE domain_media_allocation DROP CONSTRAINT "+constraint);}}
 @Test void localForeignKeyPinsSpaceAndActor(){var a=store.create(scope,"a".repeat(32),f.input(42),f.trace);assertThrows(org.springframework.dao.DataAccessException.class,()->f.jdbc.update("UPDATE domain_media_allocation SET owner_id=? WHERE media_id=?",f.ids.next(),a.media().mediaId()));}
}
